SELECT p.*, c.category_name as category_name FROM product p LEFT JOIN category c ON p.category_id = c.category_id
AND p.status = #{status}
AND p.audit_status = #{auditStatus}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.detail LIKE CONCAT('%', #{keyword}, '%'))
AND p.price >= #{minPrice}
AND p.price <= #{maxPrice}
ORDER BY p.price ASC
ORDER BY p.price DESC
ORDER BY p.sales DESC
ORDER BY p.sales ASC
ORDER BY (SELECT AVG(rating) FROM product_review WHERE product_id = p.product_id) DESC
ORDER BY p.sales DESC, p.created_at DESC

mapper.update:
UPDATE product 
SET sales = sales + #{quantity}
WHERE product_id = #{productId}
  AND status = 1

UPDATE product 
SET stock = stock - #{quantity}
WHERE product_id = #{productId} AND stock >= #{quantity}

UPDATE product 
SET reserved_stock = reserved_stock + #{quantity}
WHERE product_id = #{productId} 
AND (stock - reserved_stock) >= #{quantity}

UPDATE product 
SET reserved_stock = reserved_stock - #{quantity}
WHERE product_id = #{productId} 
AND reserved_stock >= #{quantity}

mapper.select:
SELECT (stock - IFNULL(reserved_stock, 0)) as available_stock
FROM product 
WHERE product_id = #{productId}

